=== FILE: credit_counter_props.sv ===
// Formal properties for credit_counter, written from interface_spec.md.
// Each assertion names the requirement it checks. No assume statements:
// checks that need a defined starting state are guarded by f_rst_seen,
// which is set once a reset edge has been observed.
`default_nettype none

module credit_counter_check #(
    parameter integer MAX = 4
) (
    input wire clk,
    input wire rst_n,
    input wire take,
    input wire give
);
    wire [7:0] credits;
    wire       avail;
    wire       full;
    wire       err;

    credit_counter #(.MAX(MAX)) dut (
        .clk(clk),
        .rst_n(rst_n),
        .take(take),
        .give(give),
        .credits(credits),
        .avail(avail),
        .full(full),
        .err(err)
    );

    localparam [7:0] F_MAX = MAX;

    // Input classes as the specification names them.
    wire f_take_only = take && !give;
    wire f_give_only = give && !take;
    wire f_both      = take && give;
    wire f_idle      = !take && !give;
    wire f_refused   = (f_take_only && (credits == 8'd0)) ||
                       (f_give_only && (credits == F_MAX));

    reg f_past_valid;
    reg f_rst_seen;
    initial f_past_valid = 1'b0;
    initial f_rst_seen = 1'b0;

    always @(posedge clk) begin
        f_past_valid <= 1'b1;
        if (!rst_n)
            f_rst_seen <= 1'b1;
    end

    // [req:CC-STATUS] avail and full follow credits with no clock edge.
    always @(*) begin
        assert(avail == (credits != 8'd0));
        assert(full == (credits == F_MAX));
    end

    // [req:CC-RANGE] credits never above MAX (also the induction invariant).
    always @(*) begin
        if (f_rst_seen)
            assert(credits <= F_MAX);
    end

    always @(posedge clk) begin
        // [req:CC-RESET] reset loads MAX and clears err.
        if (f_past_valid && !$past(rst_n)) begin
            assert(credits == F_MAX);
            assert(!err);
        end

        // [req:CC-TAKE] take only, credit available: down by one.
        if (f_past_valid && $past(rst_n) && $past(f_rst_seen)
                && $past(f_take_only) && ($past(credits) != 8'd0))
            assert(credits == $past(credits) - 8'd1);

        // [req:CC-GIVE] give only, room available: up by one.
        if (f_past_valid && $past(rst_n) && $past(f_rst_seen)
                && $past(f_give_only) && ($past(credits) != F_MAX))
            assert(credits == $past(credits) + 8'd1);

        // [req:CC-BOTH] take and give together: no change, nothing refused.
        if (f_past_valid && $past(rst_n) && $past(f_rst_seen) && $past(f_both)) begin
            assert(credits == $past(credits));
            assert(err == $past(err));
        end

        // [req:CC-IDLE] neither: no change.
        if (f_past_valid && $past(rst_n) && $past(f_rst_seen) && $past(f_idle))
            assert(credits == $past(credits));

        // [req:CC-UNDERFLOW] take only at zero: refused, stays zero, err set.
        if (f_past_valid && $past(rst_n) && $past(f_rst_seen)
                && $past(f_take_only) && ($past(credits) == 8'd0)) begin
            assert(credits == 8'd0);
            assert(err);
        end

        // [req:CC-OVERFLOW] give only at MAX: refused, stays MAX, err set.
        if (f_past_valid && $past(rst_n) && $past(f_rst_seen)
                && $past(f_give_only) && ($past(credits) == F_MAX)) begin
            assert(credits == F_MAX);
            assert(err);
        end

        // [req:CC-ERR-STICKY] once set, err stays high until reset.
        if (f_past_valid && $past(rst_n) && $past(err))
            assert(err);

        // err port description: err rises only after a refusal.
        if (f_past_valid && $past(rst_n) && $past(f_rst_seen) && !$past(f_refused))
            assert(err == $past(err));
    end

    // Covers: scenarios the proof must still allow (vacuity check).
    always @(posedge clk) begin
        if (f_past_valid && f_rst_seen) begin
            cover(credits == 8'd0);
            cover(f_refused && f_take_only);
            cover(f_refused && f_give_only);
            cover(f_both && (credits == 8'd0));
            cover(f_both && (credits == F_MAX));
            cover($past(f_rst_seen) && $past(rst_n) && ($past(credits) == 8'd0)
                  && (credits == 8'd1));
            cover($past(f_rst_seen) && $past(rst_n) && !$past(err) && err);
            cover(err && !rst_n);
        end
    end
endmodule

// Formal top: the checker at three MAX values (CC-PARAM), on shared free inputs.
module credit_counter_formal (
    input wire clk,
    input wire rst_n,
    input wire take,
    input wire give
);
    credit_counter_check #(.MAX(1)) u_max1 (
        .clk(clk), .rst_n(rst_n), .take(take), .give(give));
    credit_counter_check #(.MAX(4)) u_max4 (
        .clk(clk), .rst_n(rst_n), .take(take), .give(give));
    credit_counter_check #(.MAX(5)) u_max5 (
        .clk(clk), .rst_n(rst_n), .take(take), .give(give));
endmodule

`default_nettype wire
=== END FILE ===
